<?php
namespace ExcelHerbal\ERP7\Purchase;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Finance\AccountingService;use ExcelHerbal\ERP7\Finance\BranchDayGuard;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class PurchaseService{
 public static function suppliers(Actor $a):array{Guard::any($a,[Capabilities::PURCHASE_VIEW,Capabilities::PURCHASE_CREATE,Capabilities::SUPPLIER_PAYMENT]);return(array)Db::wpdb()->get_results(Db::wpdb()->prepare("SELECT id,name,mobile,gstin FROM ".Db::table('suppliers')." WHERE company_id=%d AND status='active' ORDER BY name",$a->companyId),ARRAY_A);}
 public static function createSupplier(Actor $a,string $name,string $mobile='',string $gstin=''):array{
  Guard::cap($a,Capabilities::PURCHASE_CREATE);$name=trim($name);$mobile=preg_replace('/\\D+/','',$mobile)?:'';$gstin=strtoupper(trim($gstin));if($name===''||strlen($name)>190)throw new DomainException('Valid supplier name is required.','supplier_fields_invalid',422);if($mobile!==''&&(strlen($mobile)<8||strlen($mobile)>15))throw new DomainException('Supplier mobile must contain 8 to 15 digits.','mobile_invalid',422);if($gstin!==''&&!preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/',$gstin))throw new DomainException('Valid 15-character GSTIN is required.','gstin_invalid',422);
  return Transaction::run(function()use($a,$name,$mobile,$gstin){
   $db=Db::wpdb();$companyTable=Db::table('companies');$locked=(int)$db->get_var($db->prepare("SELECT id FROM {$companyTable} WHERE id=%d AND status='active' FOR UPDATE",$a->companyId));if(!$locked)throw new DomainException('Active company not found.','company_not_found',404);$t=Db::table('suppliers');if($gstin!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND status='active' AND gstin=%s",$a->companyId,$gstin)))throw new DomainException('An active supplier already uses this GSTIN.','supplier_duplicate',409);Db::mustInsert($db,$t,['company_id'=>$a->companyId,'name'=>$name,'mobile'=>$mobile?:null,'gstin'=>$gstin?:null,'status'=>'active','created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'supplier.create','supplier',$id,[]);return['id'=>$id,'name'=>$name,'status'=>'active'];
  });
 }
 public static function openBills(Actor $a,int $branch):array{Guard::any($a,[Capabilities::PURCHASE_VIEW,Capabilities::SUPPLIER_PAYMENT]);if(!$a->hasBranch($branch))throw new DomainException('Branch is outside effective authority.','branch_forbidden',403);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT b.*,s.name supplier_name FROM ".Db::table('purchase_bills')." b JOIN ".Db::table('suppliers')." s ON s.id=b.supplier_id WHERE b.company_id=%d AND b.branch_id=%d AND b.status='posted' AND b.outstanding_amount>0 ORDER BY b.bill_date,b.id",$a->companyId,$branch),ARRAY_A);}
 public static function bill(Actor $a,int $branch,int $supplier,string $billNo,string $date,array $lines):array{$date=Input::date($date,'Bill date');Guard::branch($a,$branch,Capabilities::PURCHASE_CREATE);BranchDayGuard::assertOpen($a,$branch,$date);if(trim($billNo)===''||!$lines)throw new DomainException('Bill number and lines required.');$db=Db::wpdb();if(!(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('suppliers')." WHERE id=%d AND company_id=%d AND status='active'",$supplier,$a->companyId)))throw new DomainException('Supplier not found.');$prepared=[];$total=0.0;$seen=[];foreach($lines as$x){$pid=(int)($x['product_id']??0);$qty=(float)($x['quantity']??0);$rawCost=(float)($x['unit_cost']??0);if(!is_finite($qty)||!is_finite($rawCost)||!$pid||$qty<=0||$rawCost<0)throw new DomainException('Purchase quantity and cost must be finite and nonnegative.','purchase_amount_invalid',422);$cost=round($rawCost,4);$lt=round($qty*$cost,2);$total+=$lt;if(!is_finite($lt)||!is_finite($total))throw new DomainException('Purchase total exceeds supported amount range.','purchase_amount_invalid',422);$p=StockService::product($a,$pid);$batch=StockService::ensureBatch($a,$p,$x);$key=$pid.'|'.($batch?:0);if(isset($seen[$key]))throw new DomainException('Duplicate purchase product/batch line.','duplicate_purchase_line',422);$seen[$key]=1;$prepared[]=['product_id'=>$pid,'batch_id'=>$batch,'quantity'=>$qty,'unit_cost'=>$cost,'line_total'=>$lt];}$total=round($total,2);return Transaction::run(function()use($a,$branch,$supplier,$billNo,$date,$prepared,$total,$db){$h=Db::table('purchase_bills');Db::mustInsert($db,$h,['company_id'=>$a->companyId,'branch_id'=>$branch,'supplier_id'=>$supplier,'bill_no'=>$billNo,'bill_date'=>$date,'status'=>'posted','total_amount'=>$total,'paid_amount'=>0,'outstanding_amount'=>$total,'created_by'=>$a->employeeId,'created_at'=>Db::now()],'Duplicate supplier bill.','purchase_duplicate');$id=(int)$db->insert_id;foreach($prepared as$l){Db::mustInsert($db,Db::table('purchase_bill_lines'),['purchase_bill_id'=>$id]+$l);StockService::move($a,$branch,$l['product_id'],$l['batch_id'],null,'IN',$l['quantity'],$l['unit_cost'],'purchase_bill',$id);} $inv=AccountingService::accountByCode($a,'INVENTORY');$ap=AccountingService::accountByCode($a,'AP');$journal=AccountingService::post($a,$branch,'purchase_bill',$id,$date.' 12:00:00',[['account_id'=>(int)$inv['id'],'debit'=>$total],['account_id'=>(int)$ap['id'],'credit'=>$total,'party_type'=>'supplier','party_id'=>$supplier]],'Supplier bill '.$billNo);Db::mustUpdate($db,$h,['journal_entry_id'=>$journal],['id'=>$id]);Audit::add($a,'purchase_bill.post','purchase_bill',$id,['branch_id'=>$branch,'amount'=>$total]);return['id'=>$id,'bill_no'=>$billNo,'total_amount'=>$total,'outstanding_amount'=>$total,'status'=>'posted'];});}
 public static function payment(Actor $a,int $billId,float $amount,int $account):array{Guard::cap($a,Capabilities::SUPPLIER_PAYMENT);if(!is_finite($amount)||$amount<=0)throw new DomainException('Supplier payment must be finite and positive.','supplier_payment_amount_invalid',422);$amount=round($amount,2);if($amount<=0)throw new DomainException('Payment rounds to zero.','supplier_payment_amount_invalid',422);AccountingService::paymentAccount($a,$account);return Transaction::run(function()use($a,$billId,$amount,$account){$db=Db::wpdb();$b=Db::table('purchase_bills');$r=$db->get_row($db->prepare("SELECT * FROM {$b} WHERE id=%d AND company_id=%d AND status='posted' FOR UPDATE",$billId,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Supplier bill not found.','purchase_not_found',404);Guard::branch($a,(int)$r['branch_id'],Capabilities::SUPPLIER_PAYMENT);BranchDayGuard::assertOpen($a,(int)$r['branch_id'],Db::today());if($amount>(float)$r['outstanding_amount']+.005)throw new DomainException('Supplier advance is disabled.','supplier_advance_disabled',409);$t=Db::table('supplier_payments');Db::mustInsert($db,$t,['company_id'=>$a->companyId,'branch_id'=>(int)$r['branch_id'],'supplier_id'=>(int)$r['supplier_id'],'purchase_bill_id'=>$billId,'amount'=>$amount,'payment_account_id'=>$account,'status'=>'posted','paid_by'=>$a->employeeId,'paid_at'=>Db::now()]);$id=(int)$db->insert_id;Db::mustQuery($db,$db->prepare("UPDATE {$b} SET paid_amount=paid_amount+%f,outstanding_amount=outstanding_amount-%f WHERE id=%d",$amount,$amount,$billId));$ap=AccountingService::accountByCode($a,'AP');$journal=AccountingService::post($a,(int)$r['branch_id'],'supplier_payment',$id,Db::businessNow(),[['account_id'=>(int)$ap['id'],'debit'=>$amount,'party_type'=>'supplier','party_id'=>(int)$r['supplier_id']],['account_id'=>$account,'credit'=>$amount]],'Supplier payment');Db::mustUpdate($db,$t,['journal_entry_id'=>$journal],['id'=>$id]);Audit::add($a,'supplier_payment.post','supplier_payment',$id,['branch_id'=>(int)$r['branch_id'],'purchase_bill_id'=>$billId,'supplier_id'=>(int)$r['supplier_id'],'amount'=>$amount,'journal_entry_id'=>$journal]);return['id'=>$id,'status'=>'posted','amount'=>$amount];});}
 public static function updateSupplier(Actor $a,int $supplierId,array $data):array{
  Guard::cap($a,Capabilities::PURCHASE_CREATE);return Transaction::run(function()use($a,$supplierId,$data){
   $db=Db::wpdb();$companyTable=Db::table('companies');$db->get_var($db->prepare("SELECT id FROM {$companyTable} WHERE id=%d FOR UPDATE",$a->companyId));$t=Db::table('suppliers');$s=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$supplierId,$a->companyId),ARRAY_A);if(!$s)throw new DomainException('Supplier not found.','supplier_not_found',404);$chg=[];
   if(array_key_exists('name',$data)){$v=trim((string)$data['name']);if($v===''||strlen($v)>190)throw new DomainException('Valid supplier name is required.','supplier_fields_invalid',422);$chg['name']=$v;}
   if(array_key_exists('mobile',$data)){$v=preg_replace('/\\D+/','',(string)$data['mobile'])?:'';if($v!==''&&(strlen($v)<8||strlen($v)>15))throw new DomainException('Supplier mobile must contain 8 to 15 digits.','mobile_invalid',422);$chg['mobile']=$v?:null;}
   if(array_key_exists('gstin',$data)){$v=strtoupper(trim((string)$data['gstin']));if($v!==''&&!preg_match('/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/',$v))throw new DomainException('Valid 15-character GSTIN is required.','gstin_invalid',422);if($v!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND status='active' AND gstin=%s AND id<>%d",$a->companyId,$v,$supplierId)))throw new DomainException('An active supplier already uses this GSTIN.','supplier_duplicate',409);$chg['gstin']=$v?:null;}
   if(!$chg)throw new DomainException('No editable supplier fields supplied.','parameter_required',422);Db::mustUpdate($db,$t,$chg,['id'=>$supplierId,'company_id'=>$a->companyId]);Audit::add($a,'supplier.update','supplier',$supplierId,['fields'=>array_keys($chg)]);return['id'=>$supplierId]+$chg+['status'=>(string)$s['status']];
  });
 }
 public static function setSupplierStatus(Actor $a,int $supplierId,bool $active):array{
  Guard::cap($a,Capabilities::PURCHASE_CREATE);return Transaction::run(function()use($a,$supplierId,$active){
   $db=Db::wpdb();$companyTable=Db::table('companies');$db->get_var($db->prepare("SELECT id FROM {$companyTable} WHERE id=%d FOR UPDATE",$a->companyId));$t=Db::table('suppliers');$s=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$supplierId,$a->companyId),ARRAY_A);if(!$s)throw new DomainException('Supplier not found.','supplier_not_found',404);$target=$active?'active':'inactive';
   if(!$active){$out=(float)$db->get_var($db->prepare("SELECT COALESCE(SUM(outstanding_amount),0) FROM ".Db::table('purchase_bills')." WHERE company_id=%d AND supplier_id=%d AND status='posted' AND outstanding_amount>0",$a->companyId,$supplierId));if($out>.005)throw new DomainException('Supplier has outstanding posted bills.','supplier_deactivate_blocked',409);}
   else{$gstin=trim((string)($s['gstin']??''));if($gstin!==''&&(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM {$t} WHERE company_id=%d AND status='active' AND gstin=%s AND id<>%d",$a->companyId,$gstin,$supplierId)))throw new DomainException('Another active supplier already uses this GSTIN.','supplier_duplicate',409);}
   Db::mustUpdate($db,$t,['status'=>$target],['id'=>$supplierId,'company_id'=>$a->companyId]);Audit::add($a,'supplier.status','supplier',$supplierId,['status'=>$target]);return['id'=>$supplierId,'status'=>$target];
  });
 }


}
